/** Supplication verses (references only; the text always comes from the verified Mushaf). */
const QURAN_DUAS: [number, number, number][] = [
  [2, 201, 201], [2, 250, 250], [2, 286, 286], [3, 8, 8], [3, 16, 16], [3, 147, 147], [3, 193, 194], [7, 23, 23], [14, 40, 41], [17, 24, 24], [17, 80, 80], [18, 10, 10], [20, 25, 28],
  [21, 83, 83], [21, 87, 87], [21, 89, 89], [23, 97, 98], [23, 118, 118], [25, 65, 66], [25, 74, 74], [26, 83, 85], [27, 19, 19], [28, 16, 16], [28, 24, 24], [59, 10, 10], [71, 28, 28],
]
export const QURAN_ITEMS: QuranItem[] = QURAN_DUAS.map(([s, from, to]) => ({ id: `q-${s}-${from}-${to}`, kind: 'quran', s, from, to }))
export const collection = (id: string) => COLLECTIONS.find((c) => c.id === id)
export function itemsOf(c: Collection): Item[] {
  if (c.id === 'quran-duas') return QURAN_ITEMS
  return c.chapters.flatMap(byChapter).filter((i) => !c.timing || i.timing === 'both' || i.timing === c.timing)
}
/** Items with a verified repeat count — the only ones that can be "completed". */
export const countable = (i: Item): i is HisnItem & { count: number } => i.kind === 'dhikr' && i.status === 'source-verified' && typeof i.count === 'number' && i.count > 0
export const ALL_ITEMS: Item[] = [...HISN, ...QURAN_ITEMS]
export const findItem = (id: string) => ALL_ITEMS.find((i) => i.id === id)
/** Collections that contain an item. */
export const collectionsOf = (id: string) => COLLECTIONS.filter((c) => itemsOf(c).some((i) => i.id === id))
export const timeOfDay = (d = new Date()) => (d.getHours() >= 4 && d.getHours() < 15 ? 'morning' : 'evening') as 'morning' | 'evening'
/** Plain text of an item, for search only (display always uses the original segments). */
export const plainOf = (i: Item) => (i.kind === 'quran' ? '' : i.segs.map((s) => ('t' in s ? s.t : '')).join(' '))
export const searchKey = (t: string) => t.normalize('NFC').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED\u0640]/g, '').replace(/[إأآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
